/** Presentation only: monthly equivalents never change the tax calculation. */
export const periodAmount=(annual,period)=>annual/(period==='monthly'?12:1);
export const cashNeeded=netCash=>Math.max(0,-netCash);
export function chartValues(row,period){return {year:row.year,receipts:periodAmount(row.stages.reduce((s,p)=>s+p.income,0),period),result:periodAmount(row.totalResult,period),benefit:periodAmount(row.totalBenefit,period),cashBefore:periodAmount(row.cash,period),neededBefore:periodAmount(cashNeeded(row.cash),period),cash:periodAmount(row.afterTaxCash,period),principal:periodAmount(row.principal,period),balance:row.balance,rate:row.final.marginal};}
const money=v=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(v);
export function chartDetail(row,period){const v=chartValues(row,period);return `<div class="chart-detail-head"><strong>${v.year}</strong><span>${period==='monthly'?'Monthly average':'Annual total'}</span></div><dl><div><dt>Rental receipts</dt><dd>${money(v.receipts)}</dd></div><div><dt>Taxable rental result</dt><dd>${money(v.result)}</dd></div><div><dt>Cash needed before tax relief</dt><dd>${money(v.neededBefore)}</dd></div><div><dt>Cash flow before tax relief</dt><dd>${money(v.cashBefore)}</dd></div><div><dt>Property tax benefit</dt><dd>${money(v.benefit)}</dd></div><div><dt>Cash after tax</dt><dd>${money(v.cash)}</dd></div><div><dt>Principal repaid</dt><dd>${money(v.principal)}</dd></div><div class="detail-rate"><dt>Marginal income-tax rate</dt><dd>${v.rate.toFixed(1)}%</dd></div></dl>`;}
export function chartMarkup(rows,{period,year,visible}){if(!rows.length)return '<p class="small-text">Add a property to explore the projection.</p>';const values=rows.map(r=>chartValues(r,period)),w=670,h=245,left=54,right=18,top=20,bottom=35;const fields=[...(visible.benefit?['benefit']:[]),...(visible.cash?['cash']:[])];const all=values.flatMap(v=>fields.map(k=>v[k]));const lo=Math.min(0,...all)*1.1,hi=Math.max(1,...all)*1.15,step=(w-left-right)/Math.max(1,rows.length-1);const x=i=>left+i*step,y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);const poly=k=>values.map((v,i)=>`${x(i)},${y(v[k])}`).join(' ');const active=Math.max(0,rows.findIndex(r=>r.year===year));
const grid=Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e7ede3" stroke-dasharray="3 4"/><text x="${left-9}" y="${y(v)+3}" text-anchor="end">${Math.abs(v)>=1000?(v/1000).toFixed(1)+'k':v.toFixed(0)}</text>`;}).join('');
return `<div class="chart-wrap"><div class="chart-controls" aria-label="Chart series"><button type="button" data-action="toggle-series" data-series="benefit" aria-pressed="${visible.benefit}"><i style="background:#608348"></i>Tax benefit</button><button type="button" data-action="toggle-series" data-series="cash" aria-pressed="${visible.cash}"><i style="background:#719a9a"></i>Cash after tax</button><span>${period==='monthly'?'EUR / month · average':'EUR / year'}</span></div><svg class="chart" viewBox="0 0 ${w} ${h}" role="group" aria-label="Interactive ten-year projection. Focus or hover a year for exact figures; select to update the page.">${grid}${visible.benefit?`<polygon points="${left},${y(0)} ${poly('benefit')} ${x(rows.length-1)},${y(0)}" fill="#e9f0dc" opacity=".6"/><polyline points="${poly('benefit')}" stroke="#608348" stroke-width="2.7" fill="none"/>`:''}${visible.cash?`<polyline points="${poly('cash')}" stroke="#719a9a" stroke-width="2.3" fill="none" stroke-dasharray="5 4"/>`:''}${values.map((v,i)=>`<g class="chart-year ${i===active?'is-active':''}" data-chart-year="${v.year}"><line class="chart-guide" x1="${x(i)}" x2="${x(i)}" y1="${top}" y2="${h-bottom}" stroke="#9caf86" stroke-dasharray="3 4"/>${fields.map(k=>`<circle cx="${x(i)}" cy="${y(v[k])}" r="4" fill="${k==='benefit'?'#608348':'#719a9a'}"/>`).join('')}<text x="${x(i)}" y="${h-10}" text-anchor="middle">${v.year}</text><rect class="chart-hit" x="${Math.max(0,x(i)-step/2)}" y="0" width="${step}" height="${h}" fill="transparent" tabindex="0" role="button" aria-label="Select ${v.year}. Tax benefit ${money(v.benefit)}; cash ${money(v.cash)}; marginal tax ${v.rate.toFixed(1)} percent." aria-pressed="${i===active}" data-action="chart-select-year" data-chart-year="${v.year}"/></g>`).join('')}</svg><div class="chart-detail" role="status" aria-live="polite" aria-atomic="true">${chartDetail(rows[active],period)}</div><p class="chart-help">Hover or focus a year for exact figures. Click, tap or press Enter to select it.</p></div>`;
}
